import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Card, Table, Button, Space, Input, Select, message, Typography, Tag } from 'antd';
import { apiRequest, buildAuthHeaders } from '../api';

type SettingRow = {
  key: string;
  value: string | number | boolean;
  type?: string;
  category?: string;
};

const LLMParams: React.FC = () => {
  const headers = useMemo(() => buildAuthHeaders(), []);
  const [loading, setLoading] = useState(false);
  const [rows, setRows] = useState<SettingRow[]>([]);

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const data = await apiRequest('/admin/soul/settings/all', 'GET', null, headers);
      const items: Array<{ key: string; value: string; data_type?: string; category?: string }>
        = Array.isArray(data?.items) ? data.items : (Array.isArray(data) ? data : []);
      const filtered = items.filter(it => it.key.startsWith('llm_timeout_ms.') || it.key.startsWith('llm_retries.'))
        .map(it => ({ key: it.key, value: it.value, type: it.data_type, category: it.category }));
      setRows(filtered);
    } catch (e) {
      message.error('Не удалось загрузить настройки LLM');
    } finally {
      setLoading(false);
    }
  }, [headers]);

  useEffect(() => { load(); }, [load]);

  const [editKey, setEditKey] = useState<string>('');
  const [editValue, setEditValue] = useState<string>('');

  const saveOne = async (key: string, value: string) => {
    try {
      await apiRequest('/admin/soul/settings', 'PUT', { key, value }, headers);
      message.success('Сохранено');
      await load();
    } catch (e) {
      message.error('Ошибка сохранения');
    }
  };

  const [newType, setNewType] = useState<'timeout'|'retries'>('timeout');
  const [newFunction, setNewFunction] = useState<string>('soul_core');
  const [newTarget, setNewTarget] = useState<string>('deepseek');
  const [newValue, setNewValue] = useState<string>('6000');

  const addRow = async () => {
    const prefix = newType === 'timeout' ? 'llm_timeout_ms' : 'llm_retries';
    const key = `${prefix}.${newFunction}.${newTarget}`;
    await saveOne(key, newValue);
    setNewValue('');
  };

  const columns = [
    { title: 'Ключ', dataIndex: 'key', key: 'k', render: (v: string) => <Typography.Text code>{v}</Typography.Text> },
    { title: 'Значение', dataIndex: 'value', key: 'v', render: (_: any, row: SettingRow) => (
      editKey === row.key ? (
        <Space>
          <Input size='small' value={editValue} onChange={e => setEditValue(e.target.value)} style={{ width: 160 }} />
          <Button size='small' type='primary' onClick={() => { saveOne(row.key, editValue); setEditKey(''); }}>
            Сохранить
          </Button>
          <Button size='small' onClick={() => setEditKey('')}>Отмена</Button>
        </Space>
      ) : (
        <Space>
          <Tag>{String(row.value)}</Tag>
          <Button size='small' onClick={() => { setEditKey(row.key); setEditValue(String(row.value ?? '')); }}>Изменить</Button>
        </Space>
      )
    ) },
  ];

  return (
    <Card title="Настройки LLM: таймауты и ретраи (таблица)" extra={<Button onClick={load}>Обновить</Button>}>
      <Typography.Paragraph type="secondary">
        Формат ключей: <Typography.Text code>llm_timeout_ms.&lt;function&gt;.&lt;model|provider|default&gt;</Typography.Text> и <Typography.Text code>llm_retries.&lt;function&gt;.&lt;model|provider|default&gt;</Typography.Text>
      </Typography.Paragraph>

      <Space style={{ marginBottom: 12 }} wrap>
        <Select size='small' value={newType} onChange={(v) => setNewType(v)}
                options={[{value:'timeout',label:'timeout_ms'},{value:'retries',label:'retries'}]} />
        <Input size='small' placeholder='function (например soul_core)' value={newFunction} onChange={e=> setNewFunction(e.target.value)} style={{ width: 220 }} />
        <Input size='small' placeholder='model/provider (например deepseek)' value={newTarget} onChange={e=> setNewTarget(e.target.value)} style={{ width: 220 }} />
        <Input size='small' placeholder='value' value={newValue} onChange={e=> setNewValue(e.target.value)} style={{ width: 160 }} />
        <Button size='small' type='primary' onClick={addRow}>Добавить/Обновить</Button>
      </Space>

      <Table size='small' loading={loading} rowKey={(r) => r.key} dataSource={rows} columns={columns} pagination={{ pageSize: 10 }} />
    </Card>
  );
};

export default LLMParams;


